input.command:
cd "$ARCHON_HORIZON_ROOT" && python3 -c "
import yaml,glob,os
rows=[]
for f in glob.glob('.archon-horizon/inbox/local/items/*.yaml'):
    d=yaml.safe_load(open(f))
    b=(d.get('body') or '')
    if b.strip().startswith('CLAIM') or 'CLAIM ' in b[:200]:
        prov=(d.get('metadata') or {}).get('provenance') or {}
        rows.append((d.get('created_at',''), d['id'], prov.get('task',''), prov.get('round',''), b[:260].replace('\n',' ')))
rows.sort()
for r in rows[-30:]: print(r[0][:19], r[1], r[2], 'r'+str(r[3]), '|', r[4])
"

cd "$ARCHON_HORIZON_ROOT" && python3 -c "
import yaml,glob
rows=[]
for f in sorted(glob.glob('.archon-horizon/roadmap/items/*.yaml')):
    d=yaml.safe_load(open(f))
    o=d.get('owner') or (d.get('metadata') or {}).get('owner') or ''
    if o: rows.append((d.get('id'), d.get('status'), o))
for r in rows:
  if r[1] in ('active','pending','blocked'): print(f'{r[0]:70s} {r[1]:8s} {r[2]}')
" | grep -E "p[1-4]|review"

